<?php
if(PHP_SAPI!=='cli')exit(1);require_once __DIR__.'/legacy_operational_pure_test.php';
function lr_row(string $table,array $raw): array{return ['table'=>$table,'raw'=>$raw,'row_key'=>hash('sha256',lf_json([$table,$raw])),'reference_only'=>str_starts_with($table,'tb_'),'money_columns'=>array_values(array_intersect(array_keys($raw),['MASUK','KELUAR','SALDO','jumlah']))];}
$person=op_raw('212200001','1A');
foreach(['0.10000000009313226'=>'0.10','0.39999999990686774'=>'0.40','0.099999994039535522'=>'0.10'] as $source=>$expected){
    $rows=[$person,lr_row('tabungan',['NO_INDUK'=>'212200001','SALDO'=>$source]),lr_row('transaksi_m',['NO_INDUK'=>'212200001','MASUK'=>$expected,'TANGGAL'=>'2026-10-01'])];$original=$rows;$p=lop_prepare($rows,op_config($rows),1,'2026-10-17');
    lft_assert($p['summary']['pending']===0&&$p['summary']['savings_total']===$expected&&$p['summary']['normalized_balances']===1&&$rows===$original,'Precision policy failed');
}
$rows[1]['raw']['SALDO']='0.10004';$rows[2]['raw']['MASUK']='0.10';lft_assert((bool)lop_prepare($rows,op_config($rows),1,'2026-10-17')['pending'],'Real precision discrepancy rounded away');
$rows=[$person,lr_row('tabungan',['NO_INDUK'=>'212200001','SALDO'=>'1000']),lr_row('transaksi_m',['NO_INDUK'=>'212200001','MASUK'=>'500','TANGGAL'=>'2026-10-01']),lr_row('transaksi_m',['NO_INDUK'=>'212200001','MASUK'=>'0','KELUAR'=>null,'TANGGAL'=>'2026-10-01'])];$cfg=op_config($rows);$original=$rows;$p=lop_prepare($rows,$cfg,1,'2026-10-17');lft_assert(!$p['pending']&&$p['summary']['savings_total']==='1000.00'&&$p['summary']['source_balance_fixes']===1&&$p['summary']['zero_references']===1&&count($p['journals'])===2&&$rows===$original,'Source FIX/zero reference/delta failed');
$cfg['op_savings']['212200001']=['amount'=>'700.00','evidence'=>'Existing manual FIX must remain authoritative.','confirmed'=>true];$p=lop_prepare($rows,$cfg,1,'2026-10-17');lft_assert($p['summary']['savings_total']==='700.00'&&$p['summary']['source_balance_fixes']===0&&$p['owners']['212200001']['balance_fix']===$cfg['op_savings']['212200001'],'Manual FIX overwritten');
$rows[2]['raw']['TANGGAL']='invalid';lft_assert((bool)lop_prepare($rows,op_config($rows),1,'2026-10-17')['pending'],'Invalid journal date bypassed');
$rows=[$person,lr_row('tb_total',['NO_INDUK'=>'212200001','SALDO'=>'357']),lr_row('tb_masuk',['NO_INDUK'=>'212200001','MASUK'=>'357','TANGGAL'=>'2023-07-12'])];$original=$rows;$p=lop_prepare($rows,op_config($rows),1,'2026-10-17');lft_assert(!$p['pending']&&$p['summary']['savings_total']==='357.00'&&$p['summary']['promoted_accounts']===1&&count($p['journals'])===1&&$rows===$original,'Unique additional account not promoted once');
$rows[]=lr_row('tabungan',['NO_INDUK'=>'212200001','SALDO'=>'0']);lft_assert(lop_prepare($rows,op_config($rows),1,'2026-10-17')['summary']['promoted_accounts']===0,'Additional bank overwrote existing primary');
$rows=[$person,lr_row('bayar_du',['no_induk'=>'212200001','jumlah'=>'-1010000','th_ajaran'=>' ']),lr_row('transaksi_m',['NO_INDUK'=>null,'MASUK'=>'10000','TANGGAL'=>'2025-05-05']),lr_row('tabungan',['NO_INDUK'=>null,'SALDO'=>'10000'])];$original=$rows;$p=lop_prepare($rows,op_config($rows),1,'2026-10-17');lft_assert(!$p['pending']&&$p['summary']['du_anomalies']===1&&$p['summary']['unidentified_records']===2&&$p['summary']['payment_total']==='0.00'&&$p['summary']['savings_total']==='0.00'&&count($p['owners'])===1&&$rows===$original,'DU/anonymous references changed cash, owner or raw source');
lft_assert($p['references'][$rows[1]['row_key']]['date']===null&&$p['references'][$rows[2]['row_key']]['date']==='2025-05-05 00:00:00','Source date fabricated');
lft_assert($p===lop_prepare($rows,op_config($rows),1,'2026-10-17'),'Resolution is not deterministic');
echo "PASS: exact precision tolerance, source closing FIX, existing FIX priority, zero/noncash references, promoted bank, real date/identity holds, negative DU/unknown-owner registers and deterministic raw preservation.\n";
